// EmitDeleteFinalFields emits fields for DeletedNode.FinalFields
// (sMD_Always | sMD_DeleteFinal), including PreviousTxn* which are
// otherwise hidden.
func (l *Loan) EmitDeleteFinalFields(out map[string]any) {
	l.emitAll(out, false)
	if l.present&loanBitPreviousTxnID != 0 {
		out["PreviousTxnID"] = l.PreviousTxnID
	}
	if l.present&loanBitPreviousTxnLgrSeq != 0 {
		out["PreviousTxnLgrSeq"] = l.PreviousTxnLgrSeq
	}
}

func (l *Loan) EmitDeletePreviousFields(prev Entry, out map[string]any) {
	l.EmitPreviousFields(prev, out)
}

// PreviousTxn returns the threading values from the receiver. Empty id /
// zero seq mean the corresponding field is absent.
func (l *Loan) PreviousTxn() (string, uint32) {
	var id string
	var seq uint32
	if l.present&loanBitPreviousTxnID != 0 {
		id = l.PreviousTxnID
	}
	if l.present&loanBitPreviousTxnLgrSeq != 0 {
		seq = l.PreviousTxnLgrSeq
	}
	return id, seq
}

